@Configuration
@ComponentScan("in.coderarmy")
public class AppConfig {

    @Bean
    @Qualifier("cp")
    public PaymentService createCardPayment() {
        return new CardPayment();          // pay() prints "Paying via card"
    }

    @Bean
    @Qualifier("upi")
    public PaymentService createUpiPayment() {
        return new UpiPayment();           // pay() prints "Paying by UPI"
    }

    @Bean
    public OrderService createOrderService(@Qualifier("cp") PaymentService paymentService) {
        return new OrderService(paymentService);
    }
}

// OrderService.placeOrder(): paymentService.pay(); then System.out.println("Order placed");

public class Main {
    public static void main(String[] args) {
        ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);
        OrderService order = context.getBean(OrderService.class);
        order.placeOrder();
    }
}

@Configuration
@ComponentScan("in.coderarmy")
public class AppConfig {

    @Bean
    public User createUser() {
        return new User("Aditya", 28);
    }
}

// User is a plain class (no @Component)
ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);

@Primary
@Component
public class UPIPaymentService implements PaymentService {
    public void pay() { System.out.println("UPI payment done"); }
}

@Component
public class CardPaymentService implements PaymentService {
    public void pay() { System.out.println("Card payment done"); }
}

@Component
public class OrderService {
    private final PaymentService paymentService;

    public OrderService(@Qualifier("cardPaymentService") PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    public void placeOrder() {
        paymentService.pay();
        System.out.println("Order placed");
    }
}
